ecer produtos", "itens": ["Apresentar produtos", "Informar benefícios dos produtos", "Ensinar modo de uso dos produtos"]}, {"titulo": "Fazer fechamento de loja", "itens": ["Desligar ar-condicionado", "Desligar aparelhos de televisão e sons", "Desligar luzes (recepção, copa, estacionamento, placas de sinalização etc.)", "Acionar alarme da cerca elétrica", "Fechar portas e trancar", "Acionar alarme"]}, {"titulo": "Comunicar-se", "itens": ["Compartilhar informações relevantes de seu setor", "Demonstrar clareza na comunicação oral e escrita", "Relacionar-se com os departamentos da empresa", "Comunicar-se com fornecedores", "Elaborar relatórios", "Participar de reuniões", "Reportar-se à liderança imediata", "Comunicar-se via e-mail, WhatsApp, telefone e celular"]}]$j$::jsonb,
  sucesso = $j$["Realiza a abertura da loja conforme o procedimento e no horário", "Recebe os clientes com cordialidade", "Mantém o local de trabalho organizado e abastecido", "Registra comandas e cobranças corretamente", "Fecha o caixa sem divergências", "Apresenta os produtos e orienta o uso", "Realiza o fechamento da loja conforme o procedimento", "Comunica-se com clareza e reporta à liderança", "Mantém postura profissional durante todo o expediente"]$j$::jsonb,
  resultados = $j$[{"resp": "Abertura", "res": "Loja aberta ao público no horário, com todos os equipamentos ligados e o ambiente pronto"}, {"resp": "Atendimento", "res": "100% dos clientes recebidos com cordialidade e profissionalismo"}, {"resp": "Organização", "res": "Recepção limpa, organizada e com itens repostos"}, {"resp": "Cobrança", "res": "Comandas registradas e valores recebidos corretamente"}, {"resp": "Caixa", "res": "Caixa fechado sem divergência entre espécie, máquina de cartão e sistema"}, {"resp": "Produtos", "res": "Produtos apresentados aos clientes, com orientação de uso"}, {"resp": "Fechamento", "res": "Loja fechada seguindo todos os passos de segurança"}, {"resp": "Comunicação", "res": "Informações relevantes compartilhadas e reportadas à liderança"}, {"resp": "Postura", "res": "Atendimento alinhado aos valores e padrões da empresa"}]$j$::jsonb,
  indicadores = $j$[{"nome": "Reclamações relacionadas ao atendimento", "meta": "0", "freq": "Mensal"}, {"nome": "Divergências de caixa", "meta": "0", "freq": "Diário"}, {"nome": "Notas fiscais emitidas e enviadas", "meta": "100%", "freq": "Diário"}, {"nome": "Cumprimento dos passos de abertura de loja", "meta": "100%", "freq": "Diário"}, {"nome": "Cumprimento dos passos de fechamento de loja", "meta": "100%", "freq": "Diário"}, {"nome": "Boa convivência interna (ocorrências com a equipe)", "meta": "0", "freq": "Mensal"}, {"nome": "Pontualidade", "meta": "100%", "freq": "Diário"}, {"nome": "Satisfação do cliente", "meta": "≥ 90%", "freq": "Mensal"}]$j$::jsonb,
  escolaridade = $t$Ensino Médio completo.$t$,
  experiencia = $t$Mínimo de 1 ano em atividades de recepção e atendimento ao público; 2 anos de experiência serão considerados um diferencial.$t$,
  tecnicos = $j$["Informática", "Pacote Office básico", "Atendimento ao público", "Operação de caixa e meios de pagamento", "Emissão de nota fiscal"]$j$::jsonb,
  comportamentais = $j$["Relacionamento com pessoas", "Caráter e ética", "Parceria", "Excelência", "Comprometimento e responsabilidade", "Organização e planejamento", "Comunicação", "Cortesia e cordialidade", "Proatividade"]$j$::jsonb,
  updated_at = now()
where cargo = 'Recepcionista Caixa' and empresa = 'BSE';

